<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>ZYNKO · Verificar correo</title><link rel="icon" href="assets/img/favicon.svg"><link rel="stylesheet" href="assets/vendor/fontawesome/css/all.min.css"><link rel="stylesheet" href="assets/css/app.css"><link rel="stylesheet" href="assets/css/zynko-ui.css"></head><body class="auth auth-register"><main class="auth-card verify-card"><div class="brand login-brand"><span class="brandmark">ZY</span><div><b>ZYNKO</b><small>Verificación segura</small></div></div><?php if(!$rid||$email===''):?><div class="auth-empty"><span><i class="fa-solid fa-envelope-circle-xmark"></i></span><h1>No hay una verificación pendiente</h1><p>Inicia el registro para recibir un código nuevo.</p><a class="primary auth-link-button" href="?page=register"><i class="fa-solid fa-user-plus"></i> Crear cuenta gratis</a></div><?php else:?><div class="verify-icon"><i class="fa-solid fa-envelope-circle-check"></i></div><h1>Revisa tu correo</h1><p>Enviamos un código de 6 dígitos a <strong><?=htmlspecialchars($email)?></strong>. El código vence en 10 minutos.</p><form method="post" class="verify-form"><input type="hidden" name="action" value="registration_verify"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><label>Código de verificación</label><input class="verification-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="000000" required autofocus><button class="primary auth-primary" type="submit"><i class="fa-solid fa-circle-check"></i> Verificar y crear cuenta</button></form><form method="post" class="resend-form"><input type="hidden" name="action" value="registration_resend"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><button type="submit" class="auth-secondary"><i class="fa-solid fa-rotate"></i> Reenviar código</button></form><div class="auth-footer-link"><a href="?page=register"><i class="fa-solid fa-arrow-left"></i> Cambiar los datos del registro</a></div><?php endif?></main><script src="assets/js/zynko-ui.js"></script><script><?php if(!empty($_GET['sent'])):?>showNotify('success','Código enviado','Revisa tu bandeja de entrada y correo no deseado.');<?php endif?><?php if($verifyNotice!==''):?>showNotify('success','Código reenviado',<?=json_encode($verifyNotice,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>);<?php endif?><?php if($verifyError!==''):?>showNotify('error','No se pudo verificar',<?=json_encode($verifyError,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>);<?php endif?></script></body></html>
